Write documentation for the following code:
```
import ftplib
import sys
import os
from datetime import date
from azure.storage.fileshare import ShareServiceClient, ShareClient, ShareDirectoryClient, ShareFileClient
from azure.core.exceptions import ResourceExistsError
from time import sleep


def ftp_get_folders(ftp, path):
    ftp.cwd(path)
    folders = []
    for line in ftp.mlsd():
        if line[1]['type'] == 'dir':
            folders.append(line[0])
    return folders

def ftp_get_files(ftp, path):
    ftp.cwd(path)
    files = []
    for line in ftp.mlsd():
        if line[1]['type'] == 'file':
            files.append(line[0])
    return files

def ftp_download_file(ftp, path, filename):
    ftp.cwd(path)
    ftp.retrbinary('RETR ' + filename, open(filename, 'wb').write)

def ftp_remove_dir(ftp, path):
    for (name, properties) in ftp.mlsd(path=path):
        if name in ['.', '..']:
            continue
        elif properties['type'] == 'file':
            print("Delete file:", f"{path}/{name}")
            sleep(0.1)
            ftp.delete(f"{path}/{name}")
        elif properties['type'] == 'dir':
            print("Remove dir:", f"{path}/{name}")
            ftp_remove_dir(ftp, f"{path}/{name}")
    print("Remove final dir: ", path)
    ftp.rmd(path)



def azure_get_or_create_folder_in_share(share_client: ShareClient, folder):
    client = share_client.get_directory_client(folder)
    try:
        share_client.create_directory(folder)
    except ResourceExistsError:
        pass

