class Character:
  def __init__(self, name, desc, rels, stats, items, special):
    self.name = name
    self.desc = desc
    self.rels = rels
    self.stats = stats
    self.items = items
    self.special = special
    chars.append(self)

  def change_health(val):
    self.stats.health += val
    if self.stats.health <= 0:
      print(f'{self.name} defeated!')
    elif self.stats.health > self.stats.max_health:
      self.stats.health = self.stats.max_health
      print(f'{self.name} full healing!')
    else
      print(f'{self.name} health change: {val}')

  def change_stamina(val):
    self.stats.stamina += val
    if self.stats.stamina <= 0:
      print(f'{self.name} sleep!')
    elif self.stats.stamina > self.stats.max_stamina:
      self.stats.stamina = self.stats.max_stamina
      print(f'{self.name} full stamina!')
    else
      print(f'{self.name} stamina change: {val}')

  def is_alive(self):
    return self.stats.health > 0

  def is_active(self):
    return is_alive() and (self.stats.stamina > 0) and (not self.stats.sleep)

  def is_player(self):
    return self == player

  def time_status(self, hour):
    if hour >= self.stats.begin_time:
      if hour < self.stats.end_time:
        return 'Travel'
      elif hour < self.stats.sleep_time:
        return 'Home'
    return 'Sleep'

