```csharp
    internal bool CompareAllOperationPermitedWithExpression(IEnumerable<string> expressions, IEnumerable<string> operations)
    {
        // TODO: Make more performant with short circuit.
        var permittedOperations = operations.Where(operation => !operation.StartsWith('!')).All(operation => expressions.Any(expression => FileSystemName.MatchesSimpleExpression(expression, operation, true)));
        var deniedOperations = expressions.Where(expression => expression.StartsWith('!')).Select(expression => expression.TrimStart('!')).Any(expression => operations.Any(operation => FileSystemName.MatchesSimpleExpression(expression, operation, true)));
        return !deniedOperations && permittedOperations;
    }
