rewrite this rust function to disallow moves to unknown exits or to the same room    

fn move_player(&mut self, pid: PlayerID, direction: Direction) -> Result<RoomRef, String> {
        debug!("{:?}", self.exits);
        let (dest, name) = self.exits.get(&direction).unwrap();
        assert_ne!(self.num, *dest);
        let dest_ref = self.room_cache.get_room(*dest).unwrap();
        let (player, name) = self.players.get(&pid).unwrap();

        debug!("{:?} {:?}", dest.to_owned(), dest_ref);

        match dest_ref
            .ref_
            .accept_move(player.to_owned(), name.to_string(), self.num)
        {
            Ok(_) => {
                self.players.remove(&pid);
                Ok(dest_ref)
            }
            Err(msg) => Err(msg),
        }
    }

